export const BODY: string = "\n<p>WebP گوگل کا جدید تصویر فارمیٹ ہے، جو JPG سے 25 سے 35 فیصد چھوٹی فائل دیتا ہے، اسی معیار پر۔ یہی وجہ ہے کہ ویب سائٹیں JPG چھوڑ کر WebP اپنا رہی ہیں۔</p>\n<p>JPG کو WebP میں بدلنا آسان ہے، مگر معیار کی سیٹنگ، شفافیت اور مطابقت کو سمجھنا ضروری ہے۔ غلط سیٹنگ سے تصویر دھندلی ہو سکتی ہے، یا فائل JPG سے بڑی نکل سکتی ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ WebP کیا ہے، کتنا چھوٹا ہے، کون سی سیٹنگ کام کرتی ہے، اور اسے ورڈپریس، دکان اور بلاگ میں کیسے استعمال کریں۔ تبدیل کرنے کے لیے <a href=\"/ur/jpg-ko-webp-mein-convert-karein/\">JPG ٹو WebP</a> استعمال کریں۔</p>\n<h2 id=\"what-is-webp\">WebP کیا ہے؟</h2>\n<p>WebP گوگل کا بنایا ہوا تصویر فارمیٹ ہے، جو نقصان دہ اور بغیر نقصان دونوں کمپریشن دیتا ہے۔ یہ JPG کی طرح چھوٹا ہے اور PNG کی طرح شفافیت بھی بچاتا ہے۔</p>\n<p>WebP 2010 میں آیا تھا، مگر اب تقریباً ہر جدید براؤزر اسے کھولتا ہے۔ یہ ویب کے لیے بنایا گیا تھا، اس لیے اس کی کارکردگی ویب تصویروں پر سب سے اچھی ہے۔</p>\n<p>WebP کا مقصد JPG کو بدلنا تھا، اور ویب پر یہ مقصد تقریباً پورا ہو چکا ہے۔ پرنٹ اور پرانے سافٹ ویئر میں JPG اب بھی راج کرتا ہے۔</p>\n<h2 id=\"how-much-smaller\">WebP JPG سے کتنا چھوٹا ہے؟</h2>\n<p>اسی معیار پر WebP JPG سے 25 سے 35 فیصد چھوٹا ہوتا ہے۔ 1MB والی JPG تصویر WebP میں 650KB سے 750KB بن جاتی ہے، بغیر نظر آنے والا فرق۔</p>\n<p>بچت تصویر کی قسم پر منحصر ہے: سادہ تصویر میں زیادہ بچت ہوتی ہے، تفصیل والی میں کم۔ لیکن ہر تصویر میں کچھ نہ کچھ بچت ضرور ہوتی ہے۔</p>\n<p>سو تصویروں والی ویب سائٹ پر یہ بچت دسیوں میگا بائٹ بنتی ہے، جس سے صفحہ تیزی سے لوڈ ہوتا ہے اور وزیٹر خوش رہتا ہے۔</p>\n<h2 id=\"how-conversion-works\">JPG ٹو WebP تبدیلی کیسے کام کرتی ہے</h2>\n<p>تبدیلی میں JPG کے پکسلز کو WebP کے کمپریسر سے دوبارہ لکھا جاتا ہے۔ چونکہ JPG پہلے ہی کمپریس شدہ ہے، اس لیے تھوڑا سا اضافی نقصان ہوتا ہے۔</p>\n<p>اضافی نقصان بہت ہلکا ہوتا ہے، اگر معیار 80 سے اوپر رکھا جائے۔ اصل سے تبدیل کرنا بہتر ہے، مگر JPG سے تبدیل کرنا بھی قابل قبول ہے۔</p>\n<p>تبدیلی براؤزر میں ہوتی ہے، اس لیے تصویر سرور پر نہیں جاتی۔ فائل اپ لوڈ کریں، معیار چنیں اور WebP ڈاؤن لوڈ کریں۔</p>\n<h2 id=\"quality-settings\">معیار کی سیٹنگز جو کام کرتی ہیں</h2>\n<p>ویب تصویروں کے لیے 80 سے 85 بہترین توازن ہے: فائل چھوٹی اور تصویر تیز۔ 75 سے نیچے رنگوں کی پٹیاں نظر آنے لگتی ہیں۔</p>\n<p>متن والی تصویر کے لیے 85 سے 90 رکھیں، کیونکہ متن کے کنارے سب سے پہلے خراب ہوتے ہیں۔ پرنٹ کے لیے WebP استعمال نہ کریں، JPG یا PNG چنیں۔</p>\n<p>ہر بار نتیجہ کو مکمل سائز میں دیکھیں۔ اگر تصویر صاف لگے تو سیٹنگ درست ہے، ورنہ معیار بڑھائیں۔</p>\n<h2 id=\"browser-support\">کون سے براؤزر WebP کھولتے ہیں؟</h2>\n<p>کروم، فائر فاکس، سفاری اور ایج، سب جدید ورژن WebP کھولتے ہیں۔ 2020 کے بعد کا تقریباً ہر براؤزر WebP کو مکمل حمایت دیتا ہے۔</p>\n<p>بہت پرانے براؤزر، جیسے انٹرنیٹ ایکسپلورر، WebP نہیں کھولتے۔ اگر آپ کے وزیٹر پرانے براؤزر استعمال کرتے ہیں تو JPG نقل بھی رکھیں۔</p>\n<p>حمایت جانچنے کے لیے اپنی سائٹ کے تجزیے دیکھیں: اگر 95 فیصد وزیٹر جدید براؤزر استعمال کرتے ہیں تو WebP محفوظ ہے۔</p>\n<h2 id=\"dimensions-preserved\">ابعاد اور میٹا ڈیٹا محفوظ رہتے ہیں</h2>\n<p>تبدیلی کے بعد تصویر کے ابعاد وہی رہتے ہیں: 1920 پکسلز والی تصویر 1920 پکسلز ہی رہتی ہے۔ صرف فارمیٹ اور فائل سائز بدلتا ہے۔</p>\n<p>میٹا ڈیٹا، جیسے مقام اور کیمرے کی معلومات، اکثر ہٹا دیا جاتا ہے۔ یہ پرائیویسی کے لیے اچھا ہے، مگر اگر میٹا ڈیٹا چاہیے تو اسے الگ محفوظ رکھیں۔</p>\n<p>ابعاد جانچنے کے لیے تبدیلی کے بعد تصویر کو دوبارہ کھولیں۔ اگر ابعاد وہی ہوں تو تبدیلی درست ہوئی ہے۔</p>\n<h2 id=\"wordpress-shopify-wix\">ورڈپریس، شاپیفائی اور وکسی میں WebP استعمال کرنا</h2>\n<p>ورڈپریس 2021 سے WebP کو براہ راست قبول کرتا ہے۔ تصویر اپ لوڈ کریں اور وہ WebP کے طور پر محفوظ ہو جاتی ہے۔</p>\n<p>شاپیفائی تصویروں کو خود WebP میں بدل دیتا ہے، اس لیے دکان دار کو کچھ کرنے کی ضرورت نہیں۔ وکسی میں بھی WebP کی حمایت موجود ہے۔</p>\n<p>پرانے تھیم یا پلگ ان WebP نہ دکھائیں تو JPG نقل رکھیں۔ نیا تھیم لگانے سے پہلے WebP کی جانچ کر لیں۔</p>\n<h2 id=\"product-photos\">مصنوعات کی تصویروں کے لیے WebP</h2>\n<p>مصنوعات کی تصویروں کے لیے WebP بہترین ہے، کیونکہ دکان میں درجنوں تصویریں ہوتی ہیں اور ہر ایک کا سائز اہم ہے۔ WebP سے صفحہ تیزی سے لوڈ ہوتا ہے اور خریدار انتظار نہیں کرتا۔</p>\n<p>مصنوعات کی تصویر میں رنگ درست ہونا چاہیے، اس لیے معیار 85 رکھیں۔ کم معیار پر مصنوعات کا رنگ بدل جاتا ہے اور خریدار مایوس ہوتا ہے۔</p>\n<p>مصنوعات کی ہر تصویر کو WebP میں بدلیں، مگر اصل JPG بھی محفوظ رکھیں، تاکہ پرنٹ یا کیٹلاگ کے لیے وہ کام آئے۔</p>\n<h2 id=\"screenshots-with-text\">متن والے اسکرین شاٹ</h2>\n<p>اسکرین شاٹ میں متن ہوتا ہے، جو WebP میں JPG سے بہتر رہتا ہے۔ WebP متن کے کناروں کو تیز رکھتا ہے، خاص طور پر 85 سے اوپر معیار پر۔</p>\n<p>لیکن اسکرین شاٹ کے لیے PNG اب بھی سب سے تیز ہے۔ اگر متن سب سے اہم ہو تو PNG چنیں، ورنہ WebP کافی ہے۔</p>\n<p>اسکرین شاٹ کو WebP میں بدلنے سے پہلے متن کو زوم کر کے دیکھیں۔ اگر متن صاف پڑھا جائے تو تبدیلی کامیاب ہے۔</p>\n<h2 id=\"when-webp-is-larger\">WebP بڑا کب نکلتا ہے</h2>\n<p>کبھی کبھی WebP JPG سے بڑا نکلتا ہے، خاص طور پر جب اصل JPG بہت سخت کمپریس ہو۔ ایسی تصویر کو دوبارہ کمپریس کرنے سے فائدہ نہیں ہوتا۔</p>\n<p>سادہ اور چھوٹی تصویریں بھی WebP میں بڑی ہو سکتی ہیں، کیونکہ WebP کا ہیڈر JPG سے بڑا ہوتا ہے۔ ایسی صورت میں JPG ہی رکھیں۔</p>\n<p>تبدیلی کے بعد فائل کا سائز ہمیشہ جانچیں۔ اگر WebP بڑا ہو تو اسے مسترد کر کے JPG رکھیں۔</p>\n<h2 id=\"when-to-keep-jpg\">JPG کب رکھنا چاہیے</h2>\n<p>جب تصویر ای میل، پرنٹ یا پرانے سافٹ ویئر کے لیے ہو تو JPG رکھیں۔ WebP وہاں نہیں کھلتا، اور وصول کرنے والا تصویر دیکھ ہی نہیں پائے گا۔</p>\n<p>جب مطابقت یقینی نہ ہو تو بھی JPG رکھیں۔ JPG ہر جگہ کھلتا ہے، اس لیے وہ محفوظ انتخاب ہے۔</p>\n<p>اہم تصویر کی JPG نقل ہمیشہ محفوظ رکھیں، چاہے ویب پر WebP استعمال کریں۔ مستقبل میں JPG دوبارہ چاہیے ہو سکتا ہے۔</p>\n<h2 id=\"checking-quality\">ڈاؤن لوڈ سے پہلے معیار جانچنا</h2>\n<p>ڈاؤن لوڈ سے پہلے WebP تصویر کو مکمل سائز میں دیکھیں اور اصل سے موازنہ کریں۔ آسمان، جلد اور متن کے کنارے جانچیں۔</p>\n<p>اگر فرق نظر نہ آئے تو معیار درست ہے۔ اگر پٹیاں یا ہالہ نظر آئے تو معیار بڑھائیں اور دوبارہ تبدیل کریں۔</p>\n<p>جانچ کے لیے پیش منظر پر بھروسہ نہ کریں، کیونکہ چھوٹے پیش منظر پر نقصان چھپ جاتا ہے۔ ہمیشہ مکمل سائز دیکھیں۔</p>\n<h2 id=\"webp-for-blogs\">بلاگ کے لیے WebP</h2>\n<p>بلاگ میں درجنوں تصویریں ہوتی ہیں، اس لیے WebP سے صفحہ بہت ہلکا ہو جاتا ہے۔ قاری تیزی سے صفحہ کھولتا ہے اور زیادہ دیر رکتا ہے۔</p>\n<p>بلاگ کی ہر تصویر کو WebP میں بدلیں، مگر ہیرو تصویر کا معیار 85 رکھیں، کیونکہ وہ سب سے زیادہ نظر آتی ہے۔</p>\n<p>بلاگ میں WebP استعمال کرنے سے گوگل کی درجہ بندی بھی بہتر ہوتی ہے، کیونکہ رفتار درجہ بندی کا حصہ ہے۔</p>\n<h2 id=\"webp-for-shops\">آن لائن دکانوں کے لیے WebP</h2>\n<p>دکان میں رفتار فروخت ہے: سست صفحے سے خریدار چلا جاتا ہے۔ WebP سے مصنوعات کے صفحے تیزی سے کھلتے ہیں اور فروخت بڑھتی ہے۔</p>\n<p>دکان کی ہر تصویر کو WebP میں بدلیں، خاص طور پر تھمب نیل، کیونکہ وہ سب سے زیادہ لوڈ ہوتے ہیں۔ تھمب نیل کے لیے 80 معیار کافی ہے۔</p>\n<p>دکان میں WebP کے ساتھ JPG نقل بھی رکھیں، تاکہ پرانے براؤزر والے خریدار بھی تصویر دیکھ سکیں۔</p>\n<h2 id=\"webp-for-portfolios\">پورٹ فولیو کے لیے WebP</h2>\n<p>پورٹ فولیو میں تصویر کا معیار سب سے اہم ہے، اس لیے WebP کا معیار 85 سے 90 رکھیں۔ کم معیار پر پورٹ فولیو غیر پیشہ ورانہ لگتا ہے۔</p>\n<p>پورٹ فولیو کی تصویریں بڑی ہوتی ہیں، اس لیے WebP کی بچت بہت زیادہ ہوتی ہے۔ صفحہ تیزی سے کھلتا ہے اور کلائنٹ متاثر ہوتا ہے۔</p>\n<p>پورٹ فولیو میں اصل JPG بھی محفوظ رکھیں، تاکہ کلائنٹ مانگے تو اصل فائل دی جا سکے۔</p>\n<h2 id=\"webp-for-news\">خبروں کی ویب سائٹس کے لیے WebP</h2>\n<p>خبروں کی ویب سائٹ پر تصویریں تیزی سے بدلتی ہیں اور صفحے تیزی سے کھلنے چاہییں۔ WebP سے خبر کا صفحہ سیکنڈوں میں کھلتا ہے۔</p>\n<p>خبروں کی تصویروں کے لیے 80 معیار کافی ہے، کیونکہ وہ جلدی دیکھی جاتی ہیں اور زیادہ دیر نہیں رکتیں۔ رفتار یہاں معیار سے زیادہ اہم ہے۔</p>\n<p>خبروں میں WebP کے ساتھ JPG نقل رکھیں، کیونکہ خبر کی تصویر سوشل میڈیا پر بھی شیئر ہوتی ہے، جہاں JPG زیادہ قبول ہے۔</p>\n<h2 id=\"measuring-speed-improvement\">رفتار کی بہتری ناپنا</h2>\n<p>بہتری ناپنے کے لیے PageSpeed Insights سے پہلے اور بعد کا اسکور دیکھیں۔ WebP بدلنے کے بعد LCP اکثر آدھا سیکنڈ یا اس سے زیادہ بہتر ہوتا ہے۔</p>\n<p>صرف اسکور نہ دیکھیں، صفحے کا کل وزن بھی دیکھیں۔ اگر وزن آدھا ہو گیا ہو تو بہتری حقیقی ہے۔</p>\n<p>ہر مہینے دوبارہ ناپیں، کیونکہ نئی تصویریں اسکور دوبارہ خراب کر سکتی ہیں۔</p>\n<h2 id=\"webp-for-documentation-sites\">دستاویزی ویب سائٹس کے لیے WebP</h2>\n<p>دستاویزی ویب سائٹ میں اسکرین شاٹ اور خاکے ہوتے ہیں، جو WebP میں تیز رہتے ہیں۔ دستاویز کا صفحہ تیزی سے کھلتا ہے اور پڑھنے والا خوش رہتا ہے۔</p>\n<p>دستاویز کے اسکرین شاٹ کے لیے 85 معیار رکھیں، تاکہ متن صاف پڑھا جائے۔ خاکوں کے لیے WebP بغیر نقصان موڈ بھی استعمال ہو سکتا ہے۔</p>\n<p>دستاویز میں WebP استعمال کرنے سے پہلے اسے پرانے براؤزر پر جانچیں، کیونکہ دستاویز کے قارئین میں پرانے نظام بھی ہو سکتے ہیں۔ WebP اور JPG کا موازنہ <a href=\"/ur/blog/jpg-vs-webp/\">JPG بمقابلہ WebP</a> میں اور عملی مراحل <a href=\"/ur/blog/jpg-ko-webp-mein-kaise-convert-karein/\">JPG کو WebP میں کیسے بدلیں</a> میں دیکھیں۔ PNG سے بدلنا ہو تو <a href=\"/ur/png-ko-webp-mein-convert-karein/\">PNG ٹو WebP</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"اسی تصویر کے لیے WebP JPG سے کتنا چھوٹا ہوتا ہے؟","answer":"25 سے 35 فیصد چھوٹا ہوتا ہے، اسی معیار پر۔ 1MB والی JPG تصویر WebP میں 650KB سے 750KB بن جاتی ہے، بغیر نظر آنے والا فرق۔"},{"question":"کیا JPG کو WebP میں بدلنے سے میری تصویر کے ابعاد بدل جائیں گے؟","answer":"نہیں، ابعاد وہی رہتے ہیں۔ صرف فارمیٹ اور فائل سائز بدلتا ہے۔ 1920 پکسلز والی تصویر WebP میں بھی 1920 پکسلز ہی رہتی ہے۔"},{"question":"کیا میں ورڈپریس میں WebP تصویریں استعمال کر سکتا ہوں؟","answer":"جی ہاں، ورڈپریس 2021 سے WebP قبول کرتا ہے۔ تصویر اپ لوڈ کریں اور وہ WebP کے طور پر محفوظ ہو جاتی ہے۔ پرانے تھیم میں جانچ کر لیں۔"},{"question":"ویب سائٹ کی تصویروں کے لیے کون سی معیار سیٹنگ استعمال کروں؟","answer":"80 سے 85 بہترین توازن ہے۔ متن والی تصویر کے لیے 85 سے 90 رکھیں، کیونکہ متن کے کنارے سب سے پہلے خراب ہوتے ہیں۔"},{"question":"کیا JPG کو WebP میں بدلنا فون پر کام کرتا ہے؟","answer":"جی ہاں، کنورٹر براؤزر میں چلتا ہے اور فون پر بھی کام کرتا ہے۔ تصویر منتخب کریں، تبدیل کریں اور WebP ڈاؤن لوڈ کریں۔"},{"question":"میری تبدیل شدہ WebP اصل JPG سے بڑی کیوں ہے؟","answer":"جب اصل JPG بہت سخت کمپریس ہو تو دوبارہ کمپریس کرنے سے فائدہ نہیں ہوتا۔ چھوٹی یا سادہ تصویروں میں بھی WebP کا ہیڈر بڑا ہوتا ہے۔ ایسی صورت میں JPG ہی رکھیں۔"}];
